---
title: Extraction Fallback
description: Use text-first PDF extraction with bounded PNG fallback images.
---

# Extraction Fallback

`extractPdf(...)` is the high-level helper intended for OpenClaw-style model
input.

```ts
import { extractPdf } from "clawpdf";

const result = await extractPdf("report.pdf", {
  mode: "auto",
  maxPages: 20,
  minTextChars: 200,
  image: {
    dpi: 96,
    maxPixels: 4_000_000,
    maxDimension: 10_000,
    forms: true,
  },
});
```

Flow for `mode: "auto"`:

1. Extract text from selected pages.
2. Return text only when text length reaches `minTextChars`.
3. Otherwise render selected pages as compressed PNG images.
4. Stop rendering when image budget is exhausted.

## Modes

- `auto`: always extract text; render images only when text is short.
- `text`: extract text only.
- `images`: render images only.
- `both`: extract text and render images.

## Options

- `pages`: one-based pages to inspect.
- `maxPages`: finite positive maximum pages to inspect; the default `20` is ignored when `pages` is provided, but an explicit `maxPages` still caps that list.
- `minTextChars`: text threshold before image fallback, default `200`.
- `maxTextChars`: text output cap, default `200_000`.
- `password`: optional PDF user password.
- `engine`: optional `PdfEngine` for caller-owned reuse.
- `image.dpi` or `image.scale`: fallback render size, default `dpi: 96`.
- `image.maxPixels`: finite positive total rendered image pixel budget, default `4_000_000`.
- `image.maxDimension`: finite positive maximum rendered PNG width or height, default `10_000`.
- `image.forms`: render form widgets in fallback images, default `true`.

## Result

```ts
type ExtractResult = {
  text: string;
  images: Array<{
    page: number;
    width: number;
    height: number;
    bytes: Uint8Array;
    mimeType: "image/png";
  }>;
  pagesProcessed: number[];
  truncated: {
    text: boolean;
    images: boolean;
  };
};
```

`truncated.images` is true when any selected page is omitted or its rendered
pixel dimensions are reduced to fit the image budget. Budget checks include
rounding up to whole pixels. Floating-point noise around an exact pixel size
does not count as truncation: a Letter page at 150 DPI produces 1275 by 1650
pixels without reporting a budget cut when that size fits.

Image bytes are raw PNG data. Use `toMessageContent(result)` or
`toDataUrls(result)` when a transport needs base64.

---
title: Browser and Bundlers
description: Load the packaged PDFium WebAssembly binary in browser and bundler environments.
---

# Browser and Bundlers

Use `clawpdf/browser` in bundled browser code. It exports the same API as
`clawpdf` but pre-wires the packaged WASM URL through `import.meta.url`.

```ts
import { openPdf } from "clawpdf/browser";

await using pdf = await openPdf(file);
console.log(pdf.text({ maxPages: 3 }));
```

Custom resolution stays available:

```ts
import { createEngine } from "clawpdf/browser";

await using engine = await createEngine({
  wasmUrl: "/assets/pdfium.esm.wasm",
});
```

## Inputs

Browser inputs:

- `Uint8Array`
- `ArrayBuffer`
- URL string
- `URL`
- `Blob`

Path-like strings throw `PdfFormatError` in browsers because there is no file
system path to read.

HTTP(S) reads use the same 30-second default deadline and unlimited download
size as Node. Pass a positive `fetchMaxBytes` to `openPdf` or `extractPdf` to opt
into a body budget; `0` leaves it unlimited. Use `fetchTimeoutMs` or `signal` to
customize or cancel a request without relying on `AbortSignal.timeout` support.

## Custom Instantiation

Pass `instantiateWasm` when a runtime needs a custom WebAssembly instantiation
path:

```ts
await using engine = await createEngine({
  instantiateWasm(imports, receiveInstance) {
    // Runtime-specific instantiation hook.
  },
});
```

name: Release

on:
  push:
    tags:
      - "v*.*.*"

permissions:
  contents: read

concurrency:
  group: release-${{ github.ref }}
  cancel-in-progress: false

env:
  NODE_VERSION: 24

jobs:
  publish:
    name: Publish clawpdf
    runs-on: ubuntu-latest
    timeout-minutes: 20
    permissions:
      contents: read
      id-token: write
    steps:
      - name: Check out
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0

      - name: Set up pnpm
        uses: pnpm/action-setup@ea17c68df8912ef543352723c149a84f56e3d413 # v6.1.0
        with:
          version: 11.28.4
          run_install: false

      - name: Set up Node
        uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: ${{ env.NODE_VERSION }}
          cache: pnpm
          cache-dependency-path: pnpm-lock.yaml

      - name: Install dependencies
        run: pnpm install --frozen-lockfile

      - name: Validate package metadata
        run: |
          node <<'NODE'
          const { readFileSync } = require("node:fs");

          const pkg = JSON.parse(readFileSync("package.json", "utf8"));
          const expectedName = "clawpdf";
          const expectedAuthor = "OpenClaw Team <dev@openclaw.ai>";
          const expectedRepo = "https://github.com/openclaw/clawpdf";
          const repository = typeof pkg.repository === "string"
            ? pkg.repository
            : pkg.repository?.url;
          const normalize = (value) =>
            String(value ?? "")
              .trim()
              .replace(/^git\+/, "")
              .replace(/\.git$/i, "")
              .replace(/\/+$/, "");

          const errors = [];
          if (pkg.name !== expectedName) {
            errors.push(`package name must be ${expectedName}; found ${pkg.name ?? "<missing>"}`);
          }
          if (pkg.author !== expectedAuthor) {
            errors.push(`package author must be ${expectedAuthor}; found ${pkg.author ?? "<missing>"}`);
          }
          if (normalize(repository) !== expectedRepo) {
            errors.push(`repository URL must be ${expectedRepo}; found ${normalize(repository) || "<missing>"}`);
          }
          if (pkg.private === true) {
            errors.push("package must not be private");
          }
          if (pkg.publishConfig?.access !== "public") {
            errors.push("publishConfig.access must be public");
          }
          if (errors.length > 0) {
            for (const error of errors) console.error(error);
            process.exit(1);
          }
          NODE

      - name: Validate release tag
        env:
          RELEASE_TAG: ${{ github.ref_name }}
        run: |
          set -euo pipefail
          git fetch --no-tags origin main

          node <<'NODE'
          const { execFileSync } = require("node:child_process");
          const { readFileSync } = require("node:fs");

          const pkg = JSON.parse(readFileSync("package.json", "utf8"));
          const releaseTag = process.env.RELEASE_TAG ?? "";
          const expectedTag = `v${pkg.version}`;

          if (!/^v\d+\.\d+\.\d+$/.test(releaseTag)) {
            throw new Error(`release tag must match vX.Y.Z; received ${releaseTag || "<missing>"}`);
          }
          if (releaseTag !== expectedTag) {
            throw new Error(`release tag ${releaseTag} does not match package version ${pkg.version}`);
          }

          const releaseCommit = execFileSync("git", ["rev-list", "-n", "1", releaseTag], {
            encoding: "utf8",
          }).trim();
          const checkedOutCommit = execFileSync("git", ["rev-parse", "HEAD"], {
            encoding: "utf8",
          }).trim();
          if (releaseCommit !== checkedOutCommit) {
            throw new Error(`release tag resolves to ${releaseCommit}, but checkout is ${checkedOutCommit}`);
          }
          execFileSync("git", ["merge-base", "--is-ancestor", releaseCommit, "origin/main"]);
          NODE

      - name: Resolve npm publish state
        id: npm-version
        env:
          RELEASE_TAG: ${{ github.ref_name }}
        run: |
          set -euo pipefail
          package_name="$(node -p "require('./package.json').name")"
          package_version="$(node -p "require('./package.json').version")"
          release_commit="$(git rev-list -n 1 "${RELEASE_TAG}")"
          set +e
          output="$(npm view "${package_name}@${package_version}" gitHead --json 2>&1)"
          status=$?
          set -e
          if [ "${status}" -eq 0 ]; then
            published_commit="$(node -e 'const value = JSON.parse(process.argv[1]); process.stdout.write(typeof value === "string" ? value : "")' "${output}")"
            if [ "${published_commit}" != "${release_commit}" ]; then
              echo "${package_name}@${package_version} is already published from ${published_commit:-<unknown>}, not ${release_commit}." >&2
              exit 1
            fi
            echo "${package_name}@${package_version} is already published from this release commit; treating this as a release rerun."
            echo "published=true" >> "${GITHUB_OUTPUT}"
            exit 0
          fi
          if ! printf '%s\n' "${output}" | grep -q "E404"; then
            printf '%s\n' "${output}" >&2
            exit "${status}"
          fi
          echo "published=false" >> "${GITHUB_OUTPUT}"

      - name: Build
        run: pnpm build

      - name: Typecheck
        run: pnpm typecheck

      - name: Test
        run: pnpm test

      - name: Test package
        run: pnpm test:package

      - name: Build documentation
        run: pnpm docs:site

      - name: Verify package
        run: pnpm pack --dry-run

      - name: Publish with npm trusted publishing
        if: steps.npm-version.outputs.published != 'true'
        run: npm publish --access public --provenance

  release:
    name: Publish GitHub Release
    runs-on: ubuntu-latest
    timeout-minutes: 5
    needs: publish
    permissions:
      contents: write
    steps:
      - name: Publish release
        env:
          GH_TOKEN: ${{ github.token }}
          GH_REPO: ${{ github.repository }}
          RELEASE_TAG: ${{ github.ref_name }}
        run: gh release view "${RELEASE_TAG}" >/dev/null 2>&1 || gh release create "${RELEASE_TAG}" --verify-tag --title "${RELEASE_TAG}" --generate-notes

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

{
  "name": "clawpdf",
  "version": "0.3.3",
  "description": "Zero-dependency PDFium WASM bindings for PDF text extraction and page rendering.",
  "type": "module",
  "sideEffects": false,
  "license": "MIT",
  "author": "OpenClaw Team <dev@openclaw.ai>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/openclaw/clawpdf.git"
  },
  "bugs": {
    "url": "https://github.com/openclaw/clawpdf/issues"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./browser": {
      "types": "./dist/browser.d.ts",
      "import": "./dist/browser.js"
    },
    "./adapters": {
      "types": "./dist/adapters/index.d.ts",
      "import": "./dist/adapters/index.js"
    }
  },
  "bin": {
    "clawpdf": "dist/cli.js"
  },
  "files": [
    "dist",
    "CHANGELOG.md",
    "LICENSE",
    "README.md",
    "THIRD_PARTY_NOTICES.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json && node scripts/copy-vendor.mjs",
    "clean": "rm -rf dist site",
    "docs:site": "node scripts/build-docs-site.mjs",
    "download:pdfium": "node scripts/download-pdfium.mjs",
    "prepack": "pnpm build",
    "test": "pnpm build && vitest run",
    "test:package": "pnpm build && node scripts/test-package-e2e.mjs",
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "devDependencies": {
    "@types/node": "26.6.4",
    "typescript": "^7.0.2",
    "vitest": "5.0.3"
  },
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "packageManager": "pnpm@11.28.4"
}

import { createEngine as createCoreEngine } from "./index.js";
import { type EngineOptions, type OpenPdfOptions } from "./engine.js";
import { type ExtractOptions, type ExtractResult } from "./extract.js";
import { type PdfInput } from "./input.js";

export * from "./index.js";

const browserWasmUrl = new URL("./vendor/pdfium.esm.wasm", import.meta.url).href;
let sharedEngine: Promise<import("./engine.js").PdfEngine> | undefined;
let sharedInFlight = 0;
let sharedReleaseRequested = false;

export async function createEngine(options: EngineOptions = {}): Promise<import("./engine.js").PdfEngine> {
  return createCoreEngine({
    wasmUrl: browserWasmUrl,
    ...options,
  });
}

export async function openPdf(
  input: PdfInput,
  options: OpenPdfOptions = {},
): Promise<import("./engine.js").PdfDocument> {
  const engine = await createEngine();
  try {
    return await (engine as import("./engine.js").EngineImpl).openPrivate(input, options);
  } catch (error) {
    await engine.destroy();
    throw error;
  }
}

export async function extractPdf(input: PdfInput, options: ExtractOptions = {}): Promise<ExtractResult> {
  if (options.engine) {
    return options.engine.extract(input, withoutEngine(options));
  }

  sharedInFlight += 1;
  try {
    const engine = await getSharedEngine();
    return await engine.extract(input, options);
  } finally {
    sharedInFlight -= 1;
    if (sharedReleaseRequested && sharedInFlight === 0) {
      await disposeSharedEngine();
    }
  }
}

export async function releaseExtractEngine(): Promise<void> {
  sharedReleaseRequested = true;
  if (sharedInFlight === 0) {
    await disposeSharedEngine();
  }
}

async function getSharedEngine(): Promise<import("./engine.js").PdfEngine> {
  if (!sharedEngine) {
    sharedReleaseRequested = false;
    let nextEngine: Promise<import("./engine.js").PdfEngine>;
    nextEngine = createEngine().catch((error: unknown) => {
      if (sharedEngine === nextEngine) {
        sharedEngine = undefined;
      }
      throw error;
    });
    sharedEngine = nextEngine;
  }
  return sharedEngine;
}

async function disposeSharedEngine(): Promise<void> {
  const engine = sharedEngine;
  sharedEngine = undefined;
  sharedReleaseRequested = false;
  if (engine) {
    await (await engine).destroy();
  }
}

function withoutEngine(options: ExtractOptions): ExtractOptions {
  const { engine: _engine, ...rest } = options;
  return rest;
}

