function fakeStdout(isTTY = true): NodeJS.WritableStream & { output: string; columns: number; isTTY: boolean } {
  return {
    output: "",
    columns: 80,
    isTTY,
    write(chunk: string | Uint8Array): boolean {
      this.output += typeof chunk === "string" ? chunk : Buffer.from(chunk).toString("utf8");
      return true;
    },
  } as NodeJS.WritableStream & { output: string; columns: number; isTTY: boolean };
}

function readPngDimensions(bytes: Uint8Array): { width: number; height: number } {
  expect(bytes.subarray(0, 8)).toEqual(Uint8Array.from([137, 80, 78, 71, 13, 10, 26, 10]));
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return { width: view.getUint32(16), height: view.getUint32(20) };
}

async function rejectRemotePdf(url: string, options: { fetchMaxBytes?: number } = {}): Promise<unknown> {
  try {
    const pdf = await openPdf(url, options);
    pdf.destroy();
    throw new Error("expected openPdf to reject an oversize HTTP body");
  } catch (error) {
    return error;
  }
}

async function withPdfServer(bytes: Uint8Array, run: (baseUrl: string) => Promise<void>): Promise<void> {
  const sockets = new Set<Socket>();
  const server = createServer((request, response) => {
    if (request.url === "/ok") {
      response.writeHead(200, { "Content-Type": "application/pdf", "Content-Length": bytes.byteLength });
      response.end(bytes);
      return;
    }
    if (request.url === "/stall-body") {
      response.writeHead(200, { "Content-Type": "application/pdf", "Content-Length": bytes.byteLength + 1 });
      response.write(bytes.subarray(0, 8));
      return;
    }
    if (request.url === "/oversize-length") {
      response.writeHead(200, { "Content-Type": "application/pdf", "Content-Length": 200_000_000 });
      response.end();
      return;
    }
    if (request.url === "/declared-huge") {
      response.writeHead(200, { "Content-Type": "application/pdf", "Content-Length": Number.MAX_SAFE_INTEGER });
      response.end();
      return;
    }
    if (request.url === "/declared-unsafe") {
      response.writeHead(200, { "Content-Length": "9007199254740992" });
      response.flushHeaders();
      return;
    }
    if (request.url === "/chunked-oversize") {
      response.writeHead(200, { "Content-Type": "application/pdf", "Transfer-Encoding": "chunked" });
      response.write(bytes);
      response.write(Buffer.alloc(128));
      response.end();
      return;
    }
    if (request.url !== "/stall-headers") {
      response.writeHead(404).end();
    }
  });
  server.on("connection", (socket) => {
    sockets.add(socket);
    socket.on("close", () => sockets.delete(socket));
  });
  await new Promise<void>((resolve, reject) => {
    server.listen(0, "127.0.0.1", resolve);
    server.once("error", reject);
  });
  const address = server.address() as AddressInfo;
  try {
    await run(`http://127.0.0.1:${address.port}`);
  } finally {
    for (const socket of sockets) socket.destroy();
    await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
  }
}

function makeTextPdf(text: string | string[], options: { width?: number; height?: number; rotate?: 0 | 90 | 180 | 270; date?: string } = {}): Uint8Array {
  const pages = Array.isArray(text) ? text : [text];
  const width = options.width ?? 612;
  const height = options.height ?? 792;
  const pageObjects: number[] = [];
  const objects: string[] = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ];
  let nextObject = 4;
  for (const pageText of pages) {
    const escaped = pageText.replace(/[()\\]/g, (char) => `\\${char}`);
    const pageObject = nextObject;
    const contentObject = nextObject + 1;
    nextObject += 2;
    pageObjects.push(pageObject);
    const rotation = options.rotate === undefined ? "" : ` /Rotate ${options.rotate}`;
    objects.push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${width} ${height}]${rotation} /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentObject} 0 R >>`,
      stream(pageText ? `BT /F1 24 Tf 72 ${Math.max(1, height - 72)} Td (${escaped}) Tj ET` : ""),
    );
  }
  objects.splice(1, 0, `<< /Type /Pages /Kids [${pageObjects.map((object) => `${object} 0 R`).join(" ")}] /Count ${pages.length} >>`);
  if (options.date !== undefined) {
    const date = options.date.replace(/[()\\]/g, (char) => `\\${char}`);
    objects.push(`<< /CreationDate (${date}) /ModDate (${date}) >>`);
  }
  let body = "%PDF-1.4\n";
  const offsets = [0];
  for (let i = 0; i < objects.length; i += 1) {
    offsets.push(Buffer.byteLength(body, "utf8"));
    body += `${i + 1} 0 obj\n${objects[i]}\nendobj\n`;
  }
  const xrefOffset = Buffer.byteLength(body, "utf8");
  body += `xref\n0 ${objects.length + 1}\n`;
  body += "0000000000 65535 f \n";
  for (const offset of offsets.slice(1)) {
    body += `${String(offset).padStart(10, "0")} 00000 n \n`;
  }
  const info = options.date === undefined ? "" : ` /Info ${objects.length} 0 R`;
  body += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R${info} >>\n`;
  body += `startxref\n${xrefOffset}\n%%EOF\n`;
  return new TextEncoder().encode(body);
}

function stream(content: string): string {
  return `<< /Length ${Buffer.byteLength(content, "utf8")} >>\nstream\n${content}\nendstream`;
}

